<script setup lang="ts">
import {commandErrorStatus} from '@/composables/aippt/commandError'

import { ref,watch,onBeforeUnmount } from 'vue'
import { checkPermi } from '@/utils/permission'
import { api } from '@/api/aippt'
import useUserStore from '@/store/modules/user'
import type { Source } from '@/types/aippt'
const props=defineProps<{projectId:string;sources:Source[];inputRevision:number;locked:boolean}>(),emit=defineEmits<{changed:[]}>();const selected=ref<Source|null>(null),text=ref(''),kind=ref('text'),busy=ref(false),error=ref(''),pendingFiles=ref<File[]>([]);let addCommand:{key:string;body:Record<string,unknown>}|null=null;const uploadCommands=new Map<File,{key:string;revision:number}>()
const user=useUserStore();let targetGeneration=0,selectionGeneration=0,alive=true
function target(){return{pid:props.projectId,token:user.token,generation:targetGeneration}}
function sameTarget(own:ReturnType<typeof target>){return alive&&!!own.token&&own.pid===props.projectId&&own.token===user.token&&own.generation===targetGeneration}
watch(()=>[props.projectId,user.token],()=>{targetGeneration++;selectionGeneration++;selected.value=null;text.value='';kind.value='text';pendingFiles.value=[];addCommand=null;uploadCommands.clear();busy.value=false;error.value=''},{flush:'sync'})
onBeforeUnmount(()=>{alive=false;targetGeneration++;selectionGeneration++})
watch([kind,text],()=>{if(!busy.value)addCommand=null})
async function add(){if(busy.value||props.locked)return;const own=target();busy.value=true;try{addCommand ||= {key:crypto.randomUUID(),body:{kind:kind.value,text:text.value,input_revision:props.inputRevision}};const command=addCommand;await api.addSource(own.pid,command.body,command.key);if(!sameTarget(own))return;addCommand=null;text.value='';emit('changed')}catch(e:any){if(!sameTarget(own))return;if(commandErrorStatus(e)===409){addCommand=null;emit('changed')}error.value=e.message}finally{if(sameTarget(own))busy.value=false}}
async function upload(e:Event){const input=e.target as HTMLInputElement;pendingFiles.value.push(...Array.from(input.files||[]));input.value='';await retryUploads()}
async function retryUploads(){if(busy.value||props.locked)return;const own=target(),files=[...pendingFiles.value];busy.value=true;error.value='';const failures:string[]=[];try{for(const f of files){if(!sameTarget(own))return;try{if(f.size>10*1024*1024)throw new Error('超过10 MiB');if(!/\.(txt|md|docx|pdf)$/i.test(f.name))throw new Error('仅支持TXT、Markdown、DOCX、PDF');let command=uploadCommands.get(f);if(!command){const current=await api.project(own.pid);if(!sameTarget(own))return;command={key:crypto.randomUUID(),revision:current.input_revision};uploadCommands.set(f,command)}await api.uploadSource(own.pid,f,command.revision,command.key);if(!sameTarget(own))return;pendingFiles.value=pendingFiles.value.filter(file=>file!==f);uploadCommands.delete(f)}catch(e:any){if(!sameTarget(own))return;if(commandErrorStatus(e)===409)uploadCommands.delete(f);failures.push(`${f.name}：${e.message}`)}}if(sameTarget(own)){error.value=failures.join('；');emit('changed')}}finally{if(sameTarget(own))busy.value=false}}
defineExpose({isDirty:()=>!!text.value.trim()||pendingFiles.value.length>0||busy.value})
async function remove(s:Source){const own=target();try{await api.removeSource(own.pid,s.id,props.inputRevision);if(sameTarget(own))emit('changed')}catch(e:any){if(sameTarget(own))error.value=e.message}}
async function view(s:Source){const own=target(),selection=++selectionGeneration;selected.value={...s,sections:s.sections||[]};try{const sections=await api.sections(own.pid,s.id);if(sameTarget(own)&&selection===selectionGeneration&&selected.value?.id===s.id)selected.value.sections=sections}catch(e:any){if(sameTarget(own)&&selection===selectionGeneration)error.value=e.message}}
</script>
<template><section><el-alert v-if="locked" type="info" title="提纲已确认，先结束生成并取消确认后才能修改材料。" :closable="false"/><el-alert v-if="error" type="error" :title="error"/>
<el-table :data="sources" empty-text="尚未添加材料"><el-table-column label="材料"><template #default="{row}">{{row.name||row.filename||row.kind}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{row.parse_status||row.status||'已整理'}}</template></el-table-column><el-table-column prop="char_count" label="字数"/><el-table-column label="警告"><template #default="{row}">{{(row.warnings||[]).join('；')}}</template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button link @click="view(row)">查看章节</el-button><el-button v-hasPermi="['aippt:source:remove']" link type="danger" :disabled="locked||busy" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
<div v-if="!locked&&(checkPermi(['aippt:source:add']))" class="append"><template v-if="checkPermi(['aippt:source:add'])"><el-select v-model="kind" aria-label="材料类型"><el-option label="文字" value="text"/><el-option label="主题" value="topic"/></el-select><el-input v-model="text" :disabled="busy" type="textarea" :rows="4" :maxlength="kind==='topic'?500:200000" show-word-limit placeholder="补充材料"/><el-button v-hasPermi="['aippt:source:add']" :disabled="!text.trim()" :loading="busy" @click="add">添加材料</el-button></template><label v-if="checkPermi(['aippt:source:add'])">补传文档<input :disabled="busy" type="file" multiple accept=".txt,.md,.docx,.pdf" @change="upload"/></label><ul v-if="pendingFiles.length"><li v-for="file in pendingFiles" :key="file.name">{{file.name}}（等待重试）<el-button link :disabled="busy" @click="pendingFiles=pendingFiles.filter(f=>f!==file)">移除</el-button></li></ul><el-button v-if="pendingFiles.length&&checkPermi(['aippt:source:add'])" :loading="busy" @click="retryUploads">重试失败文件</el-button></div>
<el-drawer :model-value="!!selected" title="材料章节与定位" size="min(720px,90vw)" @close="selected=null"><template v-if="selected"><el-alert v-for="warning in selected.warnings" :key="warning" :title="warning" type="warning"/><article v-for="section in selected.sections" :key="section.id" class="section"><h3>{{section.heading||section.title||'正文'}}</h3><small>{{section.locator}} · {{section.ref||section.id}}</small><pre>{{section.text}}</pre></article><el-empty v-if="!selected.sections.length" description="尚未解析到文字，检查警告或补充材料"/></template></el-drawer></section></template>
<style scoped>.append{display:flex;flex-direction:column;gap:12px;max-width:800px;margin-top:20px}.section{border-bottom:1px solid #ebeef5;padding:12px 0}.section pre{white-space:pre-wrap;word-break:break-word;font-family:inherit;line-height:1.7}</style>
